// Host tests for the pure packet-level building blocks of the TUN engine:
// RFC 1071 checksums, IPv4 fragment reassembly and TCP sequence classification.
#include "../entry/src/main/cpp/tun_proxy.h"

#include <arpa/inet.h>
#include <cassert>
#include <cstdint>
#include <cstring>
#include <string>

using namespace charles;

namespace {

void test_ip_checksum() {
    // A well-formed IPv4 header whose checksum field is generated by the engine.
    uint8_t packet[20]{};
    auto* ip = reinterpret_cast<Ipv4Header*>(packet);
    ip->version_ihl = 0x45;
    ip->total_length = htons(40);
    ip->id = htons(1);
    ip->ttl = 64;
    ip->protocol = IPPROTO_TCP_V;
    ip->src_addr = inet_addr("10.0.0.1");
    ip->dst_addr = inet_addr("10.0.0.2");
    ip->checksum = 0;
    ip->checksum = htons(ip_checksum(ip));
    assert(ip->checksum != 0);
    assert(verify_ip_checksum(packet, sizeof(packet)));

    // Any single-bit corruption must be detected.
    packet[8] ^= 0x01;
    assert(!verify_ip_checksum(packet, sizeof(packet)));

    // Truncated packets are rejected rather than read past the buffer.
    assert(!verify_ip_checksum(packet, 19));
}

void test_tcp_checksum() {
    const uint32_t src = inet_addr("192.168.1.10");
    const uint32_t dst = inet_addr("93.184.216.34");
    uint8_t segment[40]{};
    auto* th = reinterpret_cast<TcpHeader*>(segment);
    th->src_port = htons(40000);
    th->dst_port = htons(80);
    th->seq = htonl(1000);
    th->ack = htonl(5000);
    th->data_offset_flags = htons((5u << 12) | 0x10);
    th->window = htons(65535);
    const char payload[] = "GET / HTTP/1.1\r\n\r\n";
    size_t plen = std::strlen(payload);
    std::memcpy(segment + 20, payload, plen);
    size_t seg_len = 20 + plen;

    th->checksum = 0;
    th->checksum = htons(transport_checksum_v4(src, dst, IPPROTO_TCP_V, segment, seg_len));
    assert(th->checksum != 0);

    // Independently verify: pseudo-header + segment must sum to zero.
    uint8_t framed[12 + 40]{};
    std::memcpy(framed + 0, &src, 4);
    std::memcpy(framed + 4, &dst, 4);
    framed[8] = 0;
    framed[9] = IPPROTO_TCP_V;
    uint16_t lens = htons(static_cast<uint16_t>(seg_len));
    std::memcpy(framed + 10, &lens, 2);
    std::memcpy(framed + 12, segment, seg_len);
    assert(ones_complement_checksum(framed, 12 + seg_len) == 0);

    // Corrupting one payload byte must invalidate the checksum.
    segment[25] ^= 0x80;
    uint16_t recomputed =
        htons(transport_checksum_v4(src, dst, IPPROTO_TCP_V, segment, seg_len));
    // recomputed is the checksum over the mutated stream; it must differ.
    assert(recomputed != th->checksum);
}

void test_fragment_reassembly() {
    FragmentReassembler re;
    const std::string payload =
        "0123456789abcdef0123456789abcdef01234567";  // 40 bytes
    assert(payload.size() == 40);
    const uint32_t src = inet_addr("10.1.1.1");
    const uint32_t dst = inet_addr("10.1.1.2");
    std::string out;
    std::string reason;

    // 8 + 8 + 24, offsets in bytes, last fragment clears MF.
    assert(!re.add_fragment(src, dst, IPPROTO_UDP_V, 7, 0, true,
                            reinterpret_cast<const uint8_t*>(payload.data()), 8, 1000, out,
                            reason));
    assert(!re.add_fragment(src, dst, IPPROTO_UDP_V, 7, 8, true,
                            reinterpret_cast<const uint8_t*>(payload.data() + 8), 8, 1001, out,
                            reason));
    assert(re.size() == 1);
    assert(re.add_fragment(src, dst, IPPROTO_UDP_V, 7, 16, false,
                           reinterpret_cast<const uint8_t*>(payload.data() + 16), 24, 1002, out,
                           reason));
    assert(out == payload);
    assert(re.size() == 0);

    // Overlapping, 8-byte-aligned fragments are refused and the partial entry
    // is discarded (segment [0,16) then [8,24) share the [8,16) range).
    reason.clear();
    assert(!re.add_fragment(src, dst, IPPROTO_UDP_V, 9, 0, true,
                            reinterpret_cast<const uint8_t*>(payload.data()), 16, 2000, out,
                            reason));
    assert(!re.add_fragment(src, dst, IPPROTO_UDP_V, 9, 8, true,
                            reinterpret_cast<const uint8_t*>(payload.data() + 8), 16, 2001, out,
                            reason));
    assert(!reason.empty());
    assert(re.size() == 0);

    // An unaligned fragment offset is rejected outright.
    assert(!re.add_fragment(src, dst, IPPROTO_UDP_V, 13, 7, true,
                            reinterpret_cast<const uint8_t*>(payload.data()), 8, 2500, out,
                            reason));

    // A gap means reassembly stays pending.
    assert(!re.add_fragment(src, dst, IPPROTO_UDP_V, 11, 0, true,
                            reinterpret_cast<const uint8_t*>(payload.data()), 8, 3000, out,
                            reason));
    assert(!re.add_fragment(src, dst, IPPROTO_UDP_V, 11, 16, false,
                            reinterpret_cast<const uint8_t*>(payload.data() + 16), 24, 3001, out,
                            reason));
    assert(re.size() == 1);

    // Timeout sweep reaps the stuck entry.
    re.sweep(3001 + REASM_TIMEOUT_MS + 1);
    assert(re.size() == 0);
}

void test_tcp_sequence_classification() {
    const uint32_t rcv_nxt = 1000;
    const uint32_t window = 100;
    size_t off = 0;
    size_t accept = 0;

    assert(classify_tcp_segment(rcv_nxt, 1000, 50, window, off, accept) ==
           TcpSegClass::in_order);
    assert(off == 0 && accept == 50);

    // Fully below the receive boundary: pure duplicate/retransmission.
    assert(classify_tcp_segment(rcv_nxt, 990, 10, window, off, accept) ==
           TcpSegClass::duplicate);

    // Partially old: only the five new bytes are accepted.
    assert(classify_tcp_segment(rcv_nxt, 995, 10, window, off, accept) ==
           TcpSegClass::in_order);
    assert(off == 5 && accept == 5);

    // Ahead of rcv_nxt but inside the window: queue out of order.
    assert(classify_tcp_segment(rcv_nxt, 1050, 10, window, off, accept) ==
           TcpSegClass::out_of_order);
    assert(accept == 10);

    // Entirely past the window.
    assert(classify_tcp_segment(rcv_nxt, 1200, 5, window, off, accept) ==
           TcpSegClass::beyond_window);

    // Zero-length probes.
    assert(classify_tcp_segment(rcv_nxt, 1000, 0, window, off, accept) ==
           TcpSegClass::duplicate);
    assert(classify_tcp_segment(rcv_nxt, 1001, 0, window, off, accept) ==
           TcpSegClass::beyond_window);

    // Window-clipped acceptance.
    assert(classify_tcp_segment(rcv_nxt, 1090, 50, window, off, accept) ==
           TcpSegClass::out_of_order);
    assert(accept == 10);  // only bytes 1090..1099 fit
}

void test_sequence_wraparound() {
    // Near the 32-bit wrap: arithmetic must stay modular.
    size_t off = 0;
    size_t accept = 0;
    uint32_t nxt = 0xfffffffau;
    assert(classify_tcp_segment(nxt, nxt, 20, 100, off, accept) == TcpSegClass::in_order);
    assert(accept == 20);
    // Segment starting just before the wrap and crossing it.
    assert(classify_tcp_segment(nxt, nxt - 5, 10, 100, off, accept) ==
           TcpSegClass::in_order);
    assert(off == 5 && accept == 5);
    // Out-of-order across the wrap boundary.
    uint32_t gap_seq = nxt + 10;  // wraps to 4
    assert(classify_tcp_segment(nxt, gap_seq, 5, 100, off, accept) ==
           TcpSegClass::out_of_order);
}

}  // namespace

int main() {
    test_ip_checksum();
    test_tcp_checksum();
    test_fragment_reassembly();
    test_tcp_sequence_classification();
    test_sequence_wraparound();
    return 0;
}
